style.css:
@-moz-document domain("roblox.com") {
/* 2016 Red Header Bar */
    .rbx-header {
        background-color: #e93223 !important;
        border-bottom: 2px solid #b82517 !important;
        height: 40px !important;
    }

    /* Adjust Navigation Text and Links */
    .rbx-header .rbx-navbar li a,
    .rbx-header .rbx-navbar li a:link,
    .rbx-header .rbx-navbar li a:visited {
        color: #ffffff !important;
        font-family: "Source Sans Pro", Arial, sans-serif !important;
        font-weight: 700 !important;
        font-size: 15px !important;
        text-transform: uppercase !important;
    }

    /* Hover State for Navigation Options */
    .rbx-header .rbx-navbar li a:hover {
        background-color: rgba(0, 0, 0, 0.15) !important;
        color: #ffffff !important;
    }

    /* Classic Search Bar Styling */
    .rbx-header .navbar-left .rbx-typeahead-container .input-field {
        border-radius: 0px !important;
        border: 1px solid #b82517 !important;
        background-color: #ffffff !important;
        color: #333333 !important;
    }

    /* Navigation Sidebar Adjustments */
    #navigation {
        background-color: #f2f2f2 !important;
        border-right: 1px solid #e0e0e0 !important;
    }

    /* Square Card Borders for Game Grid */
    .game-card-container, .item-card-container {
        border-radius: 0px !important;
        border: 1px solid #d6d6d6 !important;
        box-shadow: none !important;
    }
}
